import AppKit
import ImageIO

@MainActor
public final class PasteboardMonitor {
    private let store: ClipboardStore
    private let pasteboard: NSPasteboard
    private var lastChange: Int
    private var timer: Timer?
    public var onError: ((Error) -> Void)?
    private static let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "de.petermaurer.TransientPasteboardType"
    ]

    public init(store: ClipboardStore, pasteboard: NSPasteboard = .general) {
        self.store = store
        self.pasteboard = pasteboard
        lastChange = pasteboard.changeCount
    }

    public func start() {
        guard timer == nil else { return }
        lastChange = pasteboard.changeCount
        let timer = Timer(timeInterval: 0.25, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        timer.tolerance = 0.05
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    public func stop() { timer?.invalidate(); timer = nil }

    public func poll() {
        let change = pasteboard.changeCount
        guard change != lastChange else { return }
        lastChange = change
        guard pasteboard.types?.contains(where: { Self.excludedTypes.contains($0.rawValue) }) != true else { return }
        let items = pasteboard.pasteboardItems ?? []
        guard !items.contains(where: { item in
            item.types.contains(where: { Self.excludedTypes.contains($0.rawValue) })
        }) else { return }
        do {
            // Prefer images over text when an application offers both forms.
            // Never read every item's full-resolution image into a queue.
            for type in [NSPasteboard.PasteboardType.png, .tiff] {
                if let data = pasteboard.data(forType: type) {
                    guard data.count <= ImageDiskCache.byteLimit,
                          let source = CGImageSourceCreateWithData(data as CFData, nil),
                          let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
                          let width = properties[kCGImagePropertyPixelWidth] as? Int,
                          let height = properties[kCGImagePropertyPixelHeight] as? Int,
                          width > 0, height > 0, width <= 16_384, height <= 16_384,
                          width * height <= 64_000_000,
                          let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return }
                    guard pasteboard.changeCount == change else { return }
                    try store.recordImage(image)
                    return
                }
            }
            if let text = pasteboard.string(forType: .string), pasteboard.changeCount == change {
                store.recordText(text)
            }
        } catch { onError?(error) }
    }

    @discardableResult
    public func copyImage(_ image: CGImage) throws -> String? {
        let bitmap = NSBitmapImageRep(cgImage: image)
        guard let data = bitmap.representation(using: .png, properties: [:]) else {
            throw ClipboardError.encodingFailed
        }
        pasteboard.clearContents()
        guard pasteboard.setData(data, forType: .png) else { throw ClipboardError.pasteboardWriteFailed }
        lastChange = pasteboard.changeCount
        return try store.recordImage(image)
    }

    public func copyText(_ text: String) throws {
        pasteboard.clearContents()
        guard pasteboard.setString(text, forType: .string) else { throw ClipboardError.pasteboardWriteFailed }
        lastChange = pasteboard.changeCount
        store.recordText(text)
    }
}
